INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2238796, 305388, 36499, '<td valign="top">welcome back! very creative entry too. :o)</td>', 'welcome back! very creative entry too. :o)', '2006-03-19 09:47:09.000000', NULL, 0),
(2238810, 305289, 41802, '<td valign="top">*Critique Club* <br/> <br/>"Not Bifocals" defiantly meets the criteria of the pick two challenge.  Normally I would say wow all those comments, but come on look at the photo of course that makes people want to comment.  I personal thought with your fan base the score would have been higher, but hey top 50% and 60 comments not too bad. <br/> <br/>As for the photo itself, it just has to make you laugh.  It defiantly is a signature piece for you, I am really torn as to which one I do like better Peanut Butter or Cheese.  I think you will probably be remembered as the cheese man but the extra characteristics of this shot make it just a little bit better.  Like including the high heel, and something I missed during voting the peanut butter on the mustache.  Overall this is a nice clean shot with good lighting and of course excellent subject! <br/> <br/>PS I love the coach.  It looks really expensive is that the reason for generic peanut butter (just kidding)</td>', '*Critique Club*  "Not Bifocals" defiantly meets the criteria of the pick two challenge.  Normally I would say wow all those comments, but come on look at the photo of course that makes people want to comment.  I personal thought with your fan base the score would have been higher, but hey top 50% and 60 comments not too bad.  As for the photo itself, it just has to make you laugh.  It defiantly is a signature piece for you, I am really torn as to which one I do like better Peanut Butter or Cheese.  I think you will probably be remembered as the cheese man but the extra characteristics of this shot make it just a little bit better.  Like including the high heel, and something I missed during voting the peanut butter on the mustache.  Overall this is a nice clean shot with good lighting and of course excellent subject!  PS I love the coach.  It looks really expensive is that the reason for generic peanut butter (just kidding)', '2006-03-19 10:16:49.000000', NULL, 0),
(2238848, 305081, 34659, '<td valign="top">Congrats on your 25th place!  :-)</td>', 'Congrats on your 25th place!  :-)', '2006-03-19 11:17:58.000000', NULL, 0),
